       ```python
       import sys
       from math import gcd, ceil

       IM = 139968
       IA = 3877
       IC = 29573


       def build_lut(chars, probs):
           """Map each possible raw LCG value s (0..IM-1) to the symbol chosen for r = s/IM."""
           lut = bytearray(IM)
           prev = 0
           t = 0.0
           nch = len(chars)
           for i in range(nch):
               t += probs[i]
               cur = ceil(t * IM)
               if cur > IM:
                   cur = IM
               if cur > prev:
                   lut[prev:cur] = chars[i:i + 1] * (cur - prev)
               prev = cur
           if prev < IM:
               lut[prev:IM] = chars[nch - 1:nch] * (IM - prev)
           return bytes(lut)


       def main():
           n = int(sys.argv[1])
           out = sys.stdout.buffer

           lut_iub = build_lut(
               b"acgtBDHKMNRSVWY",
               (0.27, 0.12, 0.12, 0.27,
