```python
import sys


def fannkuch(n):
    count = list(range(1, n + 1))
    perm1 = list(range(n))
    r = n
    nperm = 0
    checksum = 0
    maxflips = 0

    while True:
        while r != 1:
            count[r - 1] = r
            r -= 1

        p0 = perm1[0]
        if p0:
            perm = perm1[:]
            k = p0
            flips = 0
            while k:
                perm[:k + 1] = perm[k::-1]
                k = perm[0]
                flips += 1
            if flips > maxflips:
                maxflips = flips
            if nperm & 1:
                checksum -= flips
            else:
                checksum += flips
        nperm += 1

        # rotate prefix perm1[0..r] left by one
        while True:
            if r == n:
                return checksum, maxflips
            if r == 1:
                perm1[0], perm1[1] = perm1[1], perm1[0]
            elif r == 2:
                perm1[0], perm1[1], perm1[2] = perm1[1], perm1[2], perm1[0]
            else:
                perm1.insert(r, perm1.pop(0))
            count[r] -= 1
            if count[r]:
                break
            r += 1


def main():
    n = int(sys.argv[1])
    if n < 1:
        print(0)
        print("Pfannkuchen(%d) = 0" % n)
        return
    checksum, maxflips = fannkuch(n)
    print(checksum)
    print("Pfannkuchen(%d) = %d" % (n, maxflips))


if __name__ == "__main__":
    main()
```

